"use client";

import { useState } from 'react';
import { Pencil, Trash } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';

interface Transaction {
  id: number;
  title: string;
  value: number;
  category: string;
  date: string;
}

export default function Home() {
  const [transactions, setTransactions] = useState<Transaction[]>([
    { id: 1, title: 'Salário', value: 5000, category: 'Receita', date: '2025-01-14' },
    { id: 2, title: 'Aluguel', value: -1500, category: 'Moradia', date: '2025-01-04' },
    { id: 3, title: 'Supermercado', value: -450, category: 'Alimentação', date: '2025-01-09' },
  ]);
  const [editing, setEditing] = useState<Transaction | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const handleSave = (transaction: Transaction) => {
    if (transaction.id) {
      setTransactions(prev => prev.map(t => t.id === transaction.id ? transaction : t));
    } else {
      const newTransaction = { ...transaction, id: Date.now() };
      setTransactions(prev => [...prev, newTransaction]);
    }
    setIsOpen(false);
    setEditing(null);
  };

  const handleDelete = (id: number) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const saldoAtual = transactions.reduce((acc, t) => acc + t.value, 0);
  const receitaTotal = transactions.filter(t => t.value > 0).reduce((acc, t) => acc + t.value, 0);
  const despesaTotal = transactions.filter(t => t.value < 0).reduce((acc, t) => acc + Math.abs(t.value), 0);

  return (
    <div className="p-6 space-y-6">
      <header className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Controle +</h1>
        <Button onClick={() => window.print()}>Imprimir</Button>
      </header>

      <div className="grid grid-cols-3 gap-4 text-center">
        <div className="p-4 bg-white shadow rounded">
          <p>Olá, Gabriel Macena</p>
          <h2 className="text-2xl font-bold text-green-600">R$ {saldoAtual.toFixed(2)}</h2>
          <small>Saldo atual</small>
        </div>
        <div className="p-4 bg-white shadow rounded">
          <h2 className="text-2xl font-bold">R$ {receitaTotal.toFixed(2)}</h2>
          <small>Receita total</small>
        </div>
        <div className="p-4 bg-white shadow rounded">
          <h2 className="text-2xl font-bold">R$ {despesaTotal.toFixed(2)}</h2>
          <small>Despesa total</small>
        </div>
      </div>

      <div className="flex space-x-2 overflow-x-auto">
        {["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"].map((m, i) => (
          <Button variant={i === 0 ? "default" : "outline"} key={m}>{m}</Button>
        ))}
      </div>

      <div className="bg-white p-4 shadow rounded">
        <div className="flex justify-between items-center mb-4">
          <Input placeholder="Filtrar por título" className="w-1/3" />
          <div className="space-x-2">
            <Button variant="outline">Filtro recente</Button>
            <Button variant="outline">Filtro valor</Button>
            <Dialog open={isOpen} onOpenChange={setIsOpen}>
              <DialogTrigger asChild>
                <Button onClick={() => setEditing(null)}>Adicionar</Button>
              </DialogTrigger>
              <TransactionModal transaction={editing} onSave={handleSave} />
            </Dialog>
          </div>
        </div>

        <table className="w-full text-left">
          <thead>
            <tr>
              <th className="p-2">Título</th>
              <th className="p-2">Valor</th>
              <th className="p-2">Categoria</th>
              <th className="p-2">Data</th>
              <th className="p-2">Ações</th>
            </tr>
          </thead>
          <tbody>
            {transactions.map((t) => (
              <tr key={t.id} className="border-t">
                <td className="p-2">{t.title}</td>
                <td className={`p-2 ${t.value < 0 ? 'text-red-600' : 'text-green-600'}`}>R$ {Math.abs(t.value).toFixed(2)}</td>
                <td className="p-2">{t.category}</td>
                <td className="p-2">{new Date(t.date).toLocaleDateString()}</td>
                <td className="p-2 flex space-x-2">
                  <Pencil className="cursor-pointer" onClick={() => { setEditing(t); setIsOpen(true); }} />
                  <Trash className="cursor-pointer text-red-600" onClick={() => handleDelete(t.id)} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const TransactionModal = ({ transaction, onSave }: { transaction: Transaction | null, onSave: (t: Transaction) => void }) => {
  const [form, setForm] = useState<Transaction>(
    transaction || { id: 0, title: '', value: 0, category: '', date: new Date().toISOString().split('T')[0] }
  );

  return (
    <DialogContent>
      <DialogHeader>
        <DialogTitle>{transaction ? 'Editar Transação' : 'Nova Transação'}</DialogTitle>
      </DialogHeader>
      <div className="space-y-4">
        <Input placeholder="Título" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
        <Input placeholder="Valor" type="number" value={form.value} onChange={(e) => setForm({ ...form, value: Number(e.target.value) })} />
        <Input placeholder="Categoria" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} />
        <Input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
        <Button className="w-full" onClick={() => onSave(form)}>
          Salvar
        </Button>
      </div>
    </DialogContent>
  );
};


